+func TestMuxMethodNotAllowedAllowHeader(t *testing.T) {
+	r := NewRouter()
+	r.Get("/resource", func(w http.ResponseWriter, r *http.Request) { w.Write([]byte("get")) })
+	r.Post("/resource", func(w http.ResponseWriter, r *http.Request) { w.Write([]byte("post")) })
+	r.Route("/sub", func(r Router) {
+		r.Put("/{id}", func(w http.ResponseWriter, r *http.Request) {})
+		r.Delete("/{id}", func(w http.ResponseWriter, r *http.Request) {})
+	})
+
+	ts := httptest.NewServer(r)
+	defer ts.Close()
+
+	cases := []struct {
+		method, path, allow string
+	}{
+		{"PUT", "/resource", "GET, POST"},
+		{"DELETE", "/resource", "GET, POST"},
+		{"PATCH", "/sub/42", "DELETE, PUT"},
+	}
+	for _, c := range cases {
+		resp, _ := testRequest(t, ts, c.method, c.path, nil)
+		if resp.StatusCode != 405 {
+			t.Fatalf("%s %s: expected 405, got %d", c.method, c.path, resp.StatusCode)
+		}
+		if got := resp.Header.Get("Allow"); got != c.allow {
+			t.Fatalf("%s %s: expected Allow %q, got %q", c.method, c.path, c.allow, got)
+		}
+	}
+
+	// A custom 405 handler still gets the Allow header set beforehand.
+	r.MethodNotAllowed(func(w http.ResponseWriter, r *http.Request) {
+		w.WriteHeader(405)
+		w.Write([]byte("custom"))
+	})
+	resp, body := testRequest(t, ts, "PUT", "/resource", nil)
+	if resp.Header.Get("Allow") != "GET, POST" || body != "custom" {
+		t.Fatalf("custom 405: Allow=%q body=%q", resp.Header.Get("Allow"), body)
+	}
+}
