+func TestMuxMethodNotAllowedAllowHeader(t *testing.T) {
+	r := NewRouter()
+	r.Get("/resource", func(w http.ResponseWriter, r *http.Request) {})
+	r.Post("/resource", func(w http.ResponseWriter, r *http.Request) {})
+	r.Put("/other", func(w http.ResponseWriter, r *http.Request) {})
+
+	// default 405 handler must advertise the supported methods
+	w := httptest.NewRecorder()
+	r.ServeHTTP(w, httptest.NewRequest("DELETE", "/resource", nil))
+	if w.Code != http.StatusMethodNotAllowed {
+		t.Fatalf("expected 405, got %d", w.Code)
+	}
+	if got := w.Header().Get("Allow"); got != "GET, POST" {
+		t.Fatalf("expected Allow %q, got %q", "GET, POST", got)
+	}
+
+	// a custom 405 handler still gets the Allow header
+	r.MethodNotAllowed(func(w http.ResponseWriter, r *http.Request) {
+		w.WriteHeader(http.StatusMethodNotAllowed)
+	})
+	w = httptest.NewRecorder()
+	r.ServeHTTP(w, httptest.NewRequest("PUT", "/resource", nil))
+	if got := w.Header().Get("Allow"); got != "GET, POST" {
+		t.Fatalf("expected Allow %q with custom handler, got %q", "GET, POST", got)
+	}
+
+	// a path that matches no route is a 404 and must not get an Allow header
+	w = httptest.NewRecorder()
+	r.ServeHTTP(w, httptest.NewRequest("GET", "/missing", nil))
+	if w.Code != http.StatusNotFound {
+		t.Fatalf("expected 404, got %d", w.Code)
+	}
+	if got := w.Header().Get("Allow"); got != "" {
+		t.Fatalf("expected no Allow header on 404, got %q", got)
+	}
+}

