+func TestExpr_autoderef_map_key_and_condition(t *testing.T) {
+	s := "foo"
+	b := true
+	f := false
+	env := map[string]any{
+		"bar": "x",
+		"ptr": &s,
+		"bp":  &b,
+		"fp":  &f,
+	}
+
+	tests := []struct {
+		code   string
+		expect any
+	}{
+		{`{foo: bar}[ptr]`, "x"},
+		{`{foo: "bar"}[ptr]`, "bar"},
+		{`bp ? 1 : 0`, 1},
+		{`fp ? 1 : 0`, 0},
+	}
+	for _, tt := range tests {
+		t.Run(tt.code, func(t *testing.T) {
+			program, err := expr.Compile(tt.code, expr.Env(env))
+			require.NoError(t, err)
+			out, err := expr.Run(program, env)
+			require.NoError(t, err)
+			require.Equal(t, tt.expect, out)
+		})
+	}
+}
